using System;using System.IO;using System.Runtime.InteropServices;using System.Windows.Forms;namespace SkinFusion{class TaskbarTests{[STAThread]static void Main(){string launcher=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Zephyr","Zephyr.exe");if(TaskbarBranding.LauncherPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Zephyr","renamed-runtime"))!=launcher)throw new Exception("Unstable launcher path");using(var window=new Form()){TaskbarBranding.ApplyToWindow(window.Handle,launcher);TaskbarBranding.PropertyStore store;Guid iid=typeof(TaskbarBranding.PropertyStore).GUID;Marshal.ThrowExceptionForHR(TaskbarBranding.SHGetPropertyStoreForWindow(window.Handle,ref iid,out store));try{foreach(var expected in new[]{Tuple.Create(2u,"\""+launcher+"\""),Tuple.Create(3u,launcher+",0"),Tuple.Create(4u,"Zephyr"),Tuple.Create(5u,TaskbarBranding.AppId)}){var key=new TaskbarBranding.PropertyKey{format=new Guid("9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3"),id=expected.Item1};TaskbarBranding.PropertyValue value;Marshal.ThrowExceptionForHR(store.GetValue(ref key,out value));try{if(value.type!=31||Marshal.PtrToStringUni(value.text)!=expected.Item2)throw new Exception("Incorrect taskbar property "+expected.Item1);}finally{TaskbarBranding.PropVariantClear(ref value);}}}finally{Marshal.ReleaseComObject(store);}}Console.WriteLine("PASS: taskbar uses stable Zephyr launcher, icon, display name and application ID.");}}}